package org.grimmoir.lunera.lite;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.media.*;
import android.net.Uri;
import android.os.*;
import org.json.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.*;

/** Runs real framework playback and lifecycle tests without third-party test libraries. */
public final class LiteInstrumentation extends Instrumentation {
    private PlaybackService service;
    private MainActivity activity;
    private Context context;
    private Store store;
    private Song longSong,shortSong;
    private int passed=0,failed=0;
    private boolean correctionsOnly=false,platformOnly=false;
    private final StringBuilder report=new StringBuilder();
    private final CountDownLatch connected=new CountDownLatch(1);
    private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){service=((PlaybackService.LocalBinder)b).getService();connected.countDown();}public void onServiceDisconnected(ComponentName n){}};
    private interface Step {void run()throws Exception;}
    private interface Condition {boolean ok();}
    private void test(String name,Step step){if(correctionsOnly&&!name.startsWith("embedded ID3")&&!name.startsWith("headphone disconnect"))return;if(platformOnly&&!name.startsWith("local library")&&!name.startsWith("folder exclusion")&&!name.startsWith("removing the task"))return;try{step.run();passed++;report.append("PASS ").append(name).append('\n');}catch(Throwable error){failed++;report.append("FAIL ").append(name).append(": ").append(error).append('\n');}Bundle status=new Bundle();status.putString("stream",report.substring(report.lastIndexOf("\n",Math.max(0,report.length()-2))+1));sendStatus(0,status);}
    private void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
    private void waitFor(Condition condition,long timeout,String message)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<end){final boolean[] result={false};runOnMainSync(()->result[0]=condition.ok());if(result[0])return;SystemClock.sleep(100);}throw new AssertionError(message);}
    @Override public void onCreate(Bundle args){super.onCreate(args);correctionsOnly=args!=null&&"fixtures".equals(args.getString("only"));platformOnly=args!=null&&"platform".equals(args.getString("only"));start();}
    @Override public void onStart(){
        context=getTargetContext();store=new Store(context);
        try{
            store.prefs.edit().clear().commit();new File(context.getFilesDir(),"queue.json").delete();
            activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
            runOnMainSync(()->context.bindService(new Intent(context,PlaybackService.class),connection,Context.BIND_AUTO_CREATE));
            check(connected.await(40,TimeUnit.SECONDS),"service did not bind");
            File longFile=new File(context.getFilesDir(),"test-long.wav"),shortFile=new File(context.getFilesDir(),"test-short.wav");wav(longFile,90);wav(shortFile,3);
            longSong=new Song(Uri.fromFile(longFile).toString(),"Test long song","Lunera tests",longFile.getPath(),90000,0);shortSong=new Song(Uri.fromFile(shortFile).toString(),"Test short song","Lunera tests",shortFile.getPath(),3000,0);
            test("favourites survive a fresh Store",()->{store.toggleFavourite(longSong);check(new Store(context).favourite(longSong),"favourite lost");store.toggleFavourite(longSong);check(!store.favourite(longSong),"favourite not removed");});
            test("playlist create, edit and persist",()->{JSONObject p=new JSONObject().put("Test playlist",new JSONArray().put(longSong.uri).put(shortSong.uri));store.savePlaylists(p);check(new Store(context).playlists().getJSONArray("Test playlist").length()==2,"playlist did not persist");p.put("Test playlist",new JSONArray().put(shortSong.uri));store.savePlaylists(p);check(store.playlists().getJSONArray("Test playlist").length()==1,"playlist edit lost");});
            test("local library scanner and duration filter",()->{
                String path=Environment.getExternalStorageDirectory()+"/Music/LuneraLiteTest/test-long.wav";
                if(Build.VERSION.SDK_INT>=29){
                    ContentValues values=new ContentValues();values.put(android.provider.MediaStore.Audio.Media.DISPLAY_NAME,"test-long.wav");values.put(android.provider.MediaStore.Audio.Media.MIME_TYPE,"audio/wav");values.put(android.provider.MediaStore.Audio.Media.RELATIVE_PATH,"Music/LuneraLiteTest/");values.put(android.provider.MediaStore.Audio.Media.IS_PENDING,1);
                    Uri audio=context.getContentResolver().insert(android.provider.MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);check(audio!=null,"could not create scoped audio fixture");
                    try(InputStream in=new FileInputStream(longFile);OutputStream out=context.getContentResolver().openOutputStream(audio)){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}
                    values.clear();values.put(android.provider.MediaStore.Audio.Media.IS_PENDING,0);context.getContentResolver().update(audio,values,null,null);
                    try(android.database.Cursor cursor=context.getContentResolver().query(audio,new String[]{"_data"},null,null,null)){if(cursor!=null&&cursor.moveToFirst())path=cursor.getString(0);}
                }
                final String expectedPath=path;CountDownLatch scan=new CountDownLatch(1);MediaScannerConnection.scanFile(context,new String[]{path},new String[]{"audio/wav"},(p,u)->scan.countDown());check(scan.await(40,TimeUnit.SECONDS),"scanner callback timeout");
                List<Song> songs=store.scan();boolean found=false;for(Song s:songs)if(s.path.equals(expectedPath))found=true;check(found,"test track missing from MediaStore");
                store.prefs.edit().putInt("minimumSeconds",100).commit();songs=store.scan();for(Song s:songs)check(!s.path.equals(expectedPath),"short-audio filter ignored");store.prefs.edit().putInt("minimumSeconds",0).commit();store.scan();
            });
            test("embedded ID3 lyrics and local override",()->{byte[] text="[00:00.00]Embedded lyrics".getBytes("UTF-8");ByteArrayOutputStream frame=new ByteArrayOutputStream();frame.write(new byte[]{3,'e','n','g',0});frame.write(text);byte[] payload=frame.toByteArray();ByteArrayOutputStream tag=new ByteArrayOutputStream();tag.write("USLT".getBytes("US-ASCII"));tag.write(new byte[]{0,0,0,(byte)payload.length,0,0});tag.write(payload);File file=new File(context.getFilesDir(),"embedded.mp3");try(OutputStream o=new FileOutputStream(file)){o.write(new byte[]{'I','D','3',3,0,0,0,0,0,(byte)tag.size()});o.write(tag.toByteArray());}Song song=new Song(Uri.fromFile(file).toString(),"Embedded","Test",file.getPath(),1,0);new File(context.getFilesDir(),store.lyricsFile(song)).delete();String resolved=MediaFiles.lyrics(context,song,store);Method parser=MediaFiles.class.getDeclaredMethod("id3",InputStream.class);parser.setAccessible(true);String direct;try(InputStream in=new FileInputStream(file)){direct=(String)parser.invoke(null,in);}check(resolved.contains("Embedded lyrics"),"embedded lyrics missing; resolved="+resolved+"; direct="+direct+"; bytes="+file.length());store.write(store.lyricsFile(song),"[00:00.00]Imported lyrics");check(MediaFiles.lyrics(context,song,store).contains("Imported lyrics"),"local override missing");});
            test("background import is bounded and decodable",()->{File source=new File(context.getCacheDir(),"test-background.png");Bitmap b=Bitmap.createBitmap(1500,2000,Bitmap.Config.RGB_565);b.eraseColor(0xFF303548);try(OutputStream o=new FileOutputStream(source)){b.compress(Bitmap.CompressFormat.PNG,100,o);}b.recycle();File dest=new File(context.getFilesDir(),"background.jpg");MediaFiles.importImage(context,Uri.fromFile(source),dest,1280);Bitmap result=MediaFiles.bitmap(dest,1280);check(result!=null&&result.getWidth()<=1280&&result.getHeight()<=1280,"background not bounded");result.recycle();});
            test("light, dark and system screens render",()->{for(String theme:new String[]{"light","dark","system"}){store.prefs.edit().putString("theme",theme).commit();screen("settings");screen("library");}screen("player");screen("lyrics");screen("queue");screen("library");});
            test("playback starts, advances, pauses, seeks and resumes",()->{runOnMainSync(()->service.playList(Arrays.asList(longSong,shortSong),0));waitFor(()->service.isPlaying(),30000,"playback did not start");SystemClock.sleep(1500);check(service.position()>500,"position did not advance");runOnMainSync(()->service.pause());int pos=service.position();SystemClock.sleep(500);check(Math.abs(service.position()-pos)<150,"pause did not hold position");runOnMainSync(()->{service.seek(5000);service.play();});waitFor(()->service.isPlaying()&&service.position()>=4500,15000,"seek/resume failed");});
            test("queue reorder preserves the playing song",()->{String active=service.current().uri;runOnMainSync(()->service.move(0,1));check(service.current().uri.equals(active)&&service.index==1,"playing song changed after move");runOnMainSync(()->service.move(1,0));runOnMainSync(()->service.enqueue(shortSong));int size=service.queue.size();runOnMainSync(()->service.remove(size-1));check(service.queue.size()==size-1,"queue remove failed");});
            test("media session transport controls work",()->{Field field=PlaybackService.class.getDeclaredField("session");field.setAccessible(true);android.media.session.MediaSession session=(android.media.session.MediaSession)field.get(service);android.media.session.MediaController controller=new android.media.session.MediaController(context,session.getSessionToken());controller.getTransportControls().pause();waitFor(()->!service.isPlaying(),5000,"media pause failed");controller.getTransportControls().play();waitFor(()->service.isPlaying(),15000,"media play failed");controller.getTransportControls().seekTo(2000);waitFor(()->service.position()>=1800&&service.position()<6000,5000,"media seek failed");});
            test("folder exclusion is applied by the real scanner",()->{store.prefs.edit().putString("excluded",Environment.getExternalStorageDirectory()+"/Music/LuneraLiteTest").commit();for(Song s:store.scan())check(!s.path.contains("/LuneraLiteTest/"),"excluded folder still indexed");store.prefs.edit().putString("excluded","").commit();store.scan();});
            test("backgrounding Activity keeps playback running",()->{runOnMainSync(()->activity.moveTaskToBack(true));SystemClock.sleep(1200);check(service.isPlaying(),"backgrounding stopped music");foregroundActivity();});
            test("headphone disconnect pauses playback (simulated receiver)",()->{runOnMainSync(()->service.playList(Arrays.asList(longSong,shortSong),0));waitFor(()->service.isPlaying(),15000,"headphone fixture did not start");Field field=PlaybackService.class.getDeclaredField("noisy");field.setAccessible(true);BroadcastReceiver receiver=(BroadcastReceiver)field.get(service);runOnMainSync(()->receiver.onReceive(context,new Intent(AudioManager.ACTION_AUDIO_BECOMING_NOISY)));waitFor(()->!service.isPlaying(),5000,"headphone disconnect did not pause");runOnMainSync(()->service.play());waitFor(()->service.isPlaying(),15000,"resume after headphones failed");});
            test("notification has media controls and no X action",()->{NotificationManager nm=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);android.service.notification.StatusBarNotification[] active=nm.getActiveNotifications();check(active.length>0,"no playback notification");boolean found=false;for(android.service.notification.StatusBarNotification n:active)if(n.getId()==71){found=true;Notification notification=n.getNotification();check(notification.actions!=null&&notification.actions.length==3,"expected previous/play/next actions");for(Notification.Action a:notification.actions)check(!a.title.toString().equalsIgnoreCase("close"),"close action present");}check(found,"media notification missing");});
            test("one-minute timer stops real background playback",()->{runOnMainSync(()->{service.repeat=1;service.select(0);service.setTimer(1,false);activity.moveTaskToBack(true);});waitFor(()->service.isPlaying(),15000,"timer playback did not start");waitFor(()->service.timerDeadline==0&&!service.isPlaying(),75000,"countdown did not stop background audio");foregroundActivity();});
            test("finish-song timer stops at completion without advancing",()->{runOnMainSync(()->{service.playList(Arrays.asList(shortSong,longSong),0);service.setTimer(1,true);});waitFor(()->service.isPlaying(),15000,"short track did not start");Field field=PlaybackService.class.getDeclaredField("timerFire");field.setAccessible(true);Runnable fire=(Runnable)field.get(service);runOnMainSync(()->{service.timerDeadline=SystemClock.elapsedRealtime();fire.run();});check(service.waitingForEnd&&service.isPlaying(),"timer did not wait for song");waitFor(()->!service.isPlaying()&&!service.waitingForEnd,15000,"did not stop at track end");check(service.index==0,"advanced to next song after timer");});
            test("timer cancellation clears pending stop",()->{runOnMainSync(()->{service.setTimer(1,true);service.cancelTimer();});check(service.timerDeadline==0&&!service.waitingForEnd,"timer state left active");});
            test("saved queue and position survive Store reload",()->{runOnMainSync(()->{service.playList(Arrays.asList(longSong,shortSong),0);});waitFor(()->service.isPlaying(),15000,"playback restart failed");runOnMainSync(()->{service.seek(7000);service.pause();});SystemClock.sleep(500);check(new Store(context).loadSongs("queue.json").size()==2,"queue not persisted");check(store.prefs.getInt("position",0)>=6500,"position not persisted");});
            test("removing the task stops music, timer and notification",()->{runOnMainSync(()->{if(service.current()==null)service.playList(Arrays.asList(longSong,shortSong),0);else service.play();service.setTimer(10,true);});waitFor(()->service.isPlaying(),15000,"play before dismissal failed");ActivityManager manager=(ActivityManager)context.getSystemService(Context.ACTIVITY_SERVICE);runOnMainSync(()->{for(ActivityManager.AppTask t:manager.getAppTasks())t.finishAndRemoveTask();});waitFor(()->!service.isPlaying()&&service.timerDeadline==0,15000,"task removal left playback or timer active");NotificationManager nm=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);waitFor(()->nm.getActiveNotifications().length==0,5000,"notification left after task removal");SystemClock.sleep(1500);check(!service.isPlaying(),"service revived playback");});
        }catch(Throwable e){failed++;report.append("SETUP FAILURE ").append(e).append('\n');}
        try{context.unbindService(connection);}catch(Exception ignored){}
        report.append("RESULT: ").append(passed).append(" passed, ").append(failed).append(" failed on API ").append(Build.VERSION.SDK_INT).append('\n');
        Bundle result=new Bundle();result.putString("stream",report.toString());finish(failed==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
    private void screen(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod("open",String.class);m.setAccessible(true);runOnMainSync(()->{try{m.invoke(activity,name);}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();}
    private void foregroundActivity(){runOnMainSync(()->context.startActivity(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));waitForIdleSync();}
    private static void wav(File file,int seconds)throws IOException{int rate=8000,count=rate*seconds;try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(file)))){out.writeBytes("RIFF");le(out,36+count*2,4);out.writeBytes("WAVEfmt ");le(out,16,4);le(out,1,2);le(out,1,2);le(out,rate,4);le(out,rate*2,4);le(out,2,2);le(out,16,2);out.writeBytes("data");le(out,count*2,4);for(int i=0;i<count;i++)le(out,(int)(Math.sin(i*2*Math.PI*440/rate)*2000),2);}}
    private static void le(DataOutputStream out,int value,int bytes)throws IOException{for(int i=0;i<bytes;i++)out.writeByte(value>>(8*i));}
}
